"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 step 2b: the step-2 read-outs retrained with EVERY detector class decorrelated from the truth (docs/iterations.md,
2026-11-19; approved by the author). Exploratory; local; dev for evaluation; test untouched.

Design, fixed in the log before running (everything else exactly as scripts/p1v4_readout.py, step 2):
- Same frozen model, same features (last-layer option states; "ears" = the audio encoder's pooled output), same
  logistic-regression read-outs (settings "states" and "ears"), same holdout, weight decays and epochs.
- Training edits, every train window, seed 0. Each label family gets its own independent coin flip per point:
  families = events (phone, doorbell, knock), decoy, footsteps, door, cabinet. With probability 0.5 the family is
  changed: if the 8 s window holds a real clip of the family, its detections overlapping the window are removed;
  otherwise one false detection of the family is added (class drawn within the family, confidence U(0.3, 1.0), span as
  step 2's false_span). In the unchanged half, the family's detections overlapping the window get one confidence from
  U(0.3, 1.0) when the window holds a real clip of it (so a high confidence does not mark a true label); natural false
  alarms stay. Labels outside the window are not touched. Gold answers unchanged.
- Step 2 changed only the events family; the matched-input rehearsal showed its read-outs take decoys for rings
  (version 3 followed about 90%) and never hear the user leave once the decoy, footsteps and door labels are gone.
- Predictions, fixed now (dev):
  P1 identity: the new states read-out's within-group concordance of version 1 against version 3 (R-hear, mean over
     the six matched conditions) is at least 0.70 (step 2: 0.32-0.42);
  P2 leaving: the new ears read-out's grounded group accuracy on S-move (matched mean) is at least 0.30 (step 2: 0.01);
  P3 no big loss: natural dev five-part mean of the new ears read-out at least 0.934 (ours 0.944 minus 1 point), at
     its own operating point by the plan's rule with every floor at least 0.90.
  If P1-P3 hold, the new ears read-out (and its conditional version) become main-system candidates for the freeze;
  either way the result is reported as the third rung of the training-signal ladder (natural labels -> event labels
  decorrelated -> all labels decorrelated).
Commands: extract (train forward with the new edits), fit, eval.
usage (repo root): .venv-gpu/Scripts/python.exe -X utf8 scripts/p1v4_readout_allclass.py extract|fit|eval
"""
import json
import os
import random
import sys
import time

import numpy as np

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_context as C  # noqa: E402
import p1v4_data as D  # noqa: E402
import p1v4_readout as RO  # noqa: E402
import p1v4_score as S  # noqa: E402

R = "data/p1v4/runs"
OUT = f"{R}/grounding/allclass"
FAMILIES = {"events": ("phone", "doorbell", "knock"), "decoy": ("decoy",), "footsteps": ("footsteps",),
            "door": ("door",), "cabinet": ("cabinet",)}
SEED = 0


def overlaps(s, t):
    return s[2] > t - D.WIN_S and s[1] < t


class MultiEdited(C.Context):
    """Sound lists edited per point by a list of edits: ("drop", classes, t) | ("conf", classes, t, c) |
    ("add", cls, s0, s1, c); drop and conf act on detections of `classes` overlapping the window [t - 8, t]."""

    def __init__(self, which, edits):
        super().__init__(which)
        self.edits = edits

    def point(self, r, k):
        tr, sc, tags, snd = super().point(r, k)
        for e in self.edits.get(self.pid(r, k), []):
            if e[0] == "drop":
                snd = [s for s in snd if not (s[0] in e[1] and overlaps(s, e[2]))]
            elif e[0] == "conf":
                snd = [(s[0], s[1], s[2], e[3]) if (s[0] in e[1] and overlaps(s, e[2])) else s for s in snd]
            elif e[0] == "add":
                snd = sorted(list(snd) + [tuple(e[1:])], key=lambda s: (s[1], s[0]))
        return tr, sc, tags, snd


def train_edits(rows):
    rng = random.Random(SEED)
    edits, log = {}, {f: {"real dropped": 0, "false added": 0, "real conf drawn": 0, "untouched": 0, "no room": 0}
                      for f in FAMILIES}
    for r in rows:
        for p in r["points"]:
            pid = f"{r['unit']}|{r['version']}|{p['k']}"
            t = p["t"]
            present = {c for c, _, _ in D.window_events(r, t)}
            es = []
            for fam, classes in FAMILIES.items():
                real = any(c in present for c in classes)
                if rng.random() < 0.5:
                    if real:
                        es.append(("drop", classes, t))
                        log[fam]["real dropped"] += 1
                    else:
                        span = RO.false_span(r, p, rng)
                        if span:
                            es.append(("add", rng.choice(classes), span[0], span[1], round(rng.uniform(0.3, 1.0), 3)))
                            log[fam]["false added"] += 1
                        else:
                            log[fam]["no room"] += 1
                else:
                    if real:
                        es.append(("conf", classes, t, round(rng.uniform(0.3, 1.0), 3)))
                        log[fam]["real conf drawn"] += 1
                    else:
                        log[fam]["untouched"] += 1
            if es:
                edits[pid] = es
    return edits, log


def extract():
    import soundfile as sf
    import torch
    import p1v4_l1 as L1
    D.gpu_guard()
    os.makedirs(OUT, exist_ok=True)
    rows = D.load_rows("train")
    wins = D.windows_of(rows, "train")
    rows_by = {(r["unit"], r["version"]): r for r in rows}
    edits, log = train_edits(rows)
    json.dump(log, open(f"{OUT}/train_edit_counts.json", "w"), indent=1)
    print("edit counts:", json.dumps(log), flush=True)
    ctx = MultiEdited("train", edits)
    model = L1.build()
    L1.load_new_state(model, torch.load(f"{R}/l1/l1_new.pt", weights_only=True))
    model.eval()
    items = []
    for w in wins:
        r = rows_by[w["key"]]
        text, asks = ctx.situation(r, w["k"], "full")
        qs = [q for q in ("S", "R") if any(a.startswith(q + ":") for a in asks)]
        items.append({"id": w["id"], "unit": w["unit"], "path": w["path"], "text": text,
                      "marker": "agent" if w["assistant_speaking"] else "user", "qs": qs,
                      "gold": [-1 if w["gold"].get(q) is None else
                               int(w["gold"][q] == ("stop" if q == "S" else "respond")) for q in qs]})
    H, E, QW, QT, QG = [], [], [], [], []
    t0 = time.time()
    B = 8
    for i in range(0, len(items), B):
        chunk = items[i:i + B]
        waves = torch.stack([torch.from_numpy(sf.read(it["path"], dtype="float32")[0]) for it in chunk]).cuda()
        h, e, qs, _ = RO.forward_states(model, waves, [it["text"] for it in chunk], [it["marker"] for it in chunk],
                                        [[RO.TASK[q] for q in it["qs"]] for it in chunk])
        H.append(h.astype(np.float16))
        E.append(e.astype(np.float16))
        QW.append(qs + i)
        QT += [q for it in chunk for q in it["qs"]]
        QG += [g for it in chunk for g in it["gold"]]
        if (i // B) % 500 == 0:
            print(f"train/allclass: {i + len(chunk)}/{len(items)} windows {time.time() - t0:.0f} s", flush=True)
    np.savez(f"{OUT}/feats_train_allclass.npz", states=np.concatenate(H), ears=np.concatenate(E),
             q_win=np.concatenate(QW), q_task=np.array(QT), q_gold=np.array(QG),
             ids=np.array([it["id"] for it in items]), units=np.array([it["unit"] for it in items]))
    print(f"train/allclass done: {len(items)} windows, {len(QT)} questions, {time.time() - t0:.0f} s", flush=True)


def fit():
    D.gpu_guard()
    z = dict(np.load(f"{OUT}/feats_train_allclass.npz"))
    units = z["units"][z["q_win"]]
    rng = np.random.default_rng(RO.SEED)
    uniq = np.unique(z["units"])
    hold_units = set(rng.choice(uniq, size=len(uniq) // 5, replace=False))
    hold = np.array([u in hold_units for u in units])
    log, models = {}, {}
    for setting in ("states", "ears"):
        X = RO.design(z, setting).astype(np.float32)
        for q in ("S", "R"):
            m = (z["q_task"] == q) & (z["q_gold"] >= 0)
            mu, sd = X[m].mean(0), X[m].std(0) + 1e-6
            Xs = ((X - mu) / sd).astype(np.float32)
            y = z["q_gold"]
            best = None
            for wd in RO.WDS:
                lin = RO.train_logreg(Xs[m & ~hold], y[m & ~hold], wd)
                p = np.clip(RO.predict(lin, Xs[m & hold]), 1e-7, 1 - 1e-7)
                yy = y[m & hold]
                ll = float(-np.mean(yy * np.log(p) + (1 - yy) * np.log(1 - p)))
                log[f"{setting} {q} wd {wd}"] = ll
                print(f"allclass {setting} {q} wd {wd}: holdout log loss {ll:.4f}", flush=True)
                if best is None or ll < best[0]:
                    best = (ll, wd)
            lin = RO.train_logreg(Xs[m], y[m], best[1])
            models[f"{setting}|{q}"] = {"mu": mu, "sd": sd, "w": lin.weight.detach().cpu().numpy()[0],
                                        "b": float(lin.bias.detach().cpu().numpy()[0]), "wd": best[1]}
    np.savez(f"{OUT}/readouts_allclass.npz", **{f"{k}|{f}": v for k, d in models.items() for f, v in d.items()})
    json.dump(log, open(f"{OUT}/fit_log.json", "w"), indent=1)
    print("allclass read-outs fitted:", {k: v["wd"] for k, v in models.items()}, flush=True)


def load_allclass():
    z = np.load(f"{OUT}/readouts_allclass.npz")
    out = {}
    for k in z.files:
        s, q, f = k.split("|")
        out.setdefault((s, q), {})[f] = z[k]
    return out


def eval_():
    import p1v4_combo_pilot as CP
    import p1v4_conditional as CV
    import p1v4_grounding as G
    import p1v4_grounding_report as GR
    from sklearn.metrics import roc_auc_score
    import p1v4_trust_curves as TC
    rows, rows_by = G.load("dev")
    groups = G.load_groups("dev")
    groups_map = S.load_groups("dev")
    ro_old = RO.load_readouts()
    ro_new = load_allclass()
    pr = dict(np.load(f"{RO.OUT}/ears_probe.npz"))
    cth = json.load(open("results/main_v04/conditional_dev.json"))["thresholds"]
    zn = dict(np.load(f"{RO.OUT}/feats_dev_natural.npz"))
    res = {"natural": {}, "matched": {}, "pairs": {}}
    th = {}
    for setting in ("states", "ears"):
        sc = RO.scores_of(zn, setting, ro_new)
        op = S.operating_point(rows, sc)
        th[setting] = {"S": op["th_s"], "R": op["th_r"]}
        T = S.unit_table(rows, S.decide(sc, op["th_s"], op["th_r"]), groups_map)
        m = S.metrics(T)
        res["natural"][f"all-class {setting}"] = {"th": th[setting], "primary": m["primary"], "parts": m["parts"],
                                                  "floors": m["floors"], "floors_met": op["floors_met"],
                                                  "audio": m["audio"]}

    def cond_scores(z, ro_e, th_e):
        old = RO.scores_of(z, None, ro_old)
        new = RO.scores_of(z, "ears", ro_e)
        pe = CV.probe_p(z["ears"], pr)
        route = (pe >= CV.EARS_CUT) != (z["conf"] >= CV.LABEL_TRUST)
        sc = {}
        for w, idv in enumerate(z["ids"]):
            u, v, k = idv.split("|")
            key = (u, v, int(k))
            src, tq = (new, th_e) if route[w] else (old, cth["old head"])
            sc[key] = {q: float(1 / (1 + np.exp(-(CV.logit(p) - CV.logit(tq[q]))))) for q, p in src.get(key, {}).items()}
        return sc

    sc = cond_scores(zn, ro_new, th["ears"])
    T = S.unit_table(rows, S.decide(sc, 0.5, 0.5), groups_map)
    m = S.metrics(T)
    res["natural"]["all-class conditional"] = {"primary": m["primary"], "parts": m["parts"], "floors": m["floors"],
                                               "audio": m["audio"]}
    hard = {q["key"]: q["real"] for q in TC.r_hear_points(rows, C.Context("dev"))
            if q["conf"] is not None and 0.5 <= q["conf"] < 0.9}
    hk = [k for k in hard]
    y = np.array([hard[k] for k in hk])
    for setting in ("states", "ears"):
        s = RO.scores_of(zn, setting, ro_new)
        res["natural"][f"all-class {setting}"]["hard_auc"] = float(roc_auc_score(y, [1 - s[k]["R"] for k in hk]))
    systems = {}
    for cond in G.CONDS:
        z = dict(np.load(f"{G.out_dir('dev')}/l1_{cond}.npz"))
        for name, sc, t in (("all-class states", RO.scores_of(z, "states", ro_new), th["states"]),
                            ("all-class ears", RO.scores_of(z, "ears", ro_new), th["ears"]),
                            ("all-class conditional", cond_scores(z, ro_new, th["ears"]), {"S": 0.5, "R": 0.5})):
            dec = S.decide(sc, t["S"], t["R"])
            systems.setdefault(name, {})[cond] = GR.group_eval(groups, rows_by, dec, sc)
    for name, per in systems.items():
        res["matched"][name] = {}
        for part in ("r_hear", "s_move"):
            summ = {c: GR.summarise(per[c], part) for c in G.CONDS}
            mm = [summ[c] for c in G.MATCHED]
            res["matched"][name][part] = {"by_condition": summ,
                                          "mean_matched": {f: float(np.mean([x[f] for x in mm]))
                                                           for f in ("right", "conc", "follow_event", "follow_none")}}
            if part == "r_hear":
                res["pairs"][name] = {f"conc_1_vs_{v}": float(np.mean([summ[c][f"conc_1_vs_{v}"] for c in G.MATCHED]))
                                      for v in ("2", "3")}
    p1 = res["pairs"]["all-class states"]["conc_1_vs_3"]
    p2 = res["matched"]["all-class ears"]["s_move"]["mean_matched"]["right"]
    ne = res["natural"]["all-class ears"]
    res["predictions"] = {"P1 identity (states, 1 vs 3 >= 0.70)": [p1, p1 >= 0.70],
                          "P2 leaving (ears, S-move grounded >= 0.30)": [p2, p2 >= 0.30],
                          "P3 no big loss (ears natural >= 0.934, floors met)": [ne["primary"],
                                                                                 ne["primary"] >= 0.934 and
                                                                                 ne["floors_met"]]}
    json.dump(res, open("results/main_v04/readout_allclass_dev.json", "w"), indent=1)
    for n, x in res["natural"].items():
        print(f"natural {n:24s} mean {x['primary']:.3f} audio {x['audio']:.3f} floors "
              + " ".join(f"{k}:{v:.2f}" for k, v in x["floors"].items())
              + (f" hard AUC {x['hard_auc']:.3f}" if "hard_auc" in x else ""))
    for n, x in res["matched"].items():
        for part in ("r_hear", "s_move"):
            mm = x[part]["mean_matched"]
            print(f"matched {n:24s} {part:7s} grounded {mm['right']:.3f} conc {mm['conc']:.3f} follow event "
                  f"{mm['follow_event']:.2f} none {mm['follow_none']:.2f}")
    print("pairs:", json.dumps(res["pairs"]))
    print("predictions:", json.dumps(res["predictions"]))


if __name__ == "__main__":
    {"extract": extract, "fit": fit, "eval": eval_}[sys.argv[1]]()
